<?php
/**
 * Server configuration.
 *
 * Do not edit this file for a deployment. Instead either:
 *   - copy config.local.php.example to config.local.php and set your values, or
 *   - set the GRACE_NOTES_DB_PATH environment variable (e.g. SetEnv in Apache).
 *
 * Precedence: environment variable > config.local.php > defaults below.
 *
 * Strongly recommended: point db_path at a location OUTSIDE the web root,
 * e.g. /home/youruser/private/grace-notes/database.sqlite, so the database
 * can never be downloaded directly over HTTP.
 */

$config = [
    // Default keeps the legacy location so existing installs keep working.
    'db_path' => __DIR__ . '/database.sqlite',
];

$localConfig = __DIR__ . '/config.local.php';
if (is_file($localConfig)) {
    $overrides = require $localConfig;
    if (is_array($overrides)) {
        $config = array_merge($config, $overrides);
    }
}

$envDbPath = getenv('GRACE_NOTES_DB_PATH');
if ($envDbPath !== false && trim($envDbPath) !== '') {
    $config['db_path'] = trim($envDbPath);
}

return $config;
